-- ------------------------------------------------------------------
-- MovieLinkBD database schema (PostgreSQL 14+ / Supabase)
-- Keep in sync with database/schema.sqlite.sql
-- Generated by `php bin/console.php migrate` on pgsql. Safe to re-run.
-- ------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS titles (
    id            BIGSERIAL PRIMARY KEY,
    slug          TEXT     NOT NULL UNIQUE,
    title         TEXT     NOT NULL,
    type          TEXT     NOT NULL DEFAULT 'movie'
                  CHECK (type IN ('movie','series','anime','drama','animation')),
    year          INTEGER,
    quality       TEXT,
    language      TEXT,            -- canonical slug for /language/{slug}
    language_raw  TEXT,            -- verbatim label, e.g. Dual [Hindi-Tamil]
    languages     TEXT,            -- every matched slug: |hindi|tamil|
    rating        REAL,
    views         BIGINT   NOT NULL DEFAULT 0,
    poster        TEXT,
    ep_label      TEXT,
    ep_state      TEXT     CHECK (ep_state IS NULL OR ep_state IN ('added','completed','part')),
    status        TEXT     NOT NULL DEFAULT 'completed'
                  CHECK (status IN ('completed','ongoing','upcoming')),
    synopsis      TEXT,
    runtime       TEXT,
    ott_slug      TEXT,
    is_pinned     INTEGER  NOT NULL DEFAULT 0,
    is_adult      INTEGER  NOT NULL DEFAULT 0,
    is_new        INTEGER  NOT NULL DEFAULT 0,
    is_upcoming   INTEGER  NOT NULL DEFAULT 0,
    release_date  TEXT,
    created_at    TEXT     NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
    updated_at    TEXT     NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);
CREATE INDEX IF NOT EXISTS idx_titles_type    ON titles (type);
CREATE INDEX IF NOT EXISTS idx_titles_lang    ON titles (language);
CREATE INDEX IF NOT EXISTS idx_titles_views   ON titles (views DESC);
CREATE INDEX IF NOT EXISTS idx_titles_updated ON titles (updated_at DESC);

CREATE TABLE IF NOT EXISTS genres (
    id    BIGSERIAL PRIMARY KEY,
    slug  TEXT NOT NULL UNIQUE,
    name  TEXT NOT NULL,
    icon  TEXT
);

CREATE TABLE IF NOT EXISTS title_genres (
    title_id BIGINT NOT NULL REFERENCES titles (id) ON DELETE CASCADE,
    genre_id BIGINT NOT NULL REFERENCES genres (id) ON DELETE CASCADE,
    PRIMARY KEY (title_id, genre_id)
);
CREATE INDEX IF NOT EXISTS idx_title_genres_genre ON title_genres (genre_id);

CREATE TABLE IF NOT EXISTS collections (
    id          BIGSERIAL PRIMARY KEY,
    slug        TEXT NOT NULL UNIQUE,
    name        TEXT NOT NULL,
    description TEXT,
    -- pipe separated match tokens: |hindi|hindi dubbed|
    keywords    TEXT,
    sort        INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS collection_items (
    collection_id BIGINT  NOT NULL REFERENCES collections (id) ON DELETE CASCADE,
    title_id      BIGINT  NOT NULL REFERENCES titles (id) ON DELETE CASCADE,
    sort          INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (collection_id, title_id)
);

CREATE TABLE IF NOT EXISTS ott_platforms (
    id   BIGSERIAL PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    logo TEXT,
    sort INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS download_links (
    id       BIGSERIAL PRIMARY KEY,
    title_id BIGINT NOT NULL REFERENCES titles (id) ON DELETE CASCADE,
    label    TEXT NOT NULL,
    quality  TEXT,
    size     TEXT,
    url      TEXT NOT NULL,
    sort     INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_links_title ON download_links (title_id, sort);

CREATE TABLE IF NOT EXISTS episodes (
    id          BIGSERIAL PRIMARY KEY,
    title_id    BIGINT  NOT NULL REFERENCES titles (id) ON DELETE CASCADE,
    season      INTEGER NOT NULL DEFAULT 1,
    episode     INTEGER NOT NULL,
    name        TEXT,
    released_at TEXT,
    UNIQUE (title_id, season, episode)
);

CREATE TABLE IF NOT EXISTS notices (
    id      BIGSERIAL PRIMARY KEY,
    message TEXT NOT NULL,
    style   TEXT NOT NULL DEFAULT 'new',
    color   TEXT NOT NULL DEFAULT '#2ad99a',
    active  INTEGER NOT NULL DEFAULT 1,
    sort    INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS pages (
    id         BIGSERIAL PRIMARY KEY,
    slug       TEXT NOT NULL UNIQUE,
    title      TEXT NOT NULL,
    body       TEXT NOT NULL,
    updated_at TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS settings (
    key   TEXT PRIMARY KEY,
    value TEXT
);

-- API registry: powers /api (docs), /api/index.json and the admin panel.
CREATE TABLE IF NOT EXISTS api_endpoints (
    id        BIGSERIAL PRIMARY KEY,
    method    TEXT NOT NULL DEFAULT 'GET',
    path      TEXT NOT NULL UNIQUE,
    category  TEXT NOT NULL DEFAULT 'core',
    summary   TEXT NOT NULL,
    params    TEXT,
    sample    TEXT,
    is_public INTEGER NOT NULL DEFAULT 1,
    sort      INTEGER NOT NULL DEFAULT 0
);

-- Request log for /status + admin "traffic" widget. Trimmed automatically.
CREATE TABLE IF NOT EXISTS api_logs (
    id          BIGSERIAL PRIMARY KEY,
    method      TEXT    NOT NULL,
    path        TEXT    NOT NULL,
    status      INTEGER NOT NULL,
    duration_ms INTEGER NOT NULL DEFAULT 0,
    ip          TEXT,
    created_at  TEXT    NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);
CREATE INDEX IF NOT EXISTS idx_api_logs_created ON api_logs (created_at DESC);

-- Admin sessions (see src/Core/SessionHandler.php). Kept in the database so
-- the panel keeps working on serverless hosts with an ephemeral /tmp.
CREATE TABLE IF NOT EXISTS sessions (
    id            TEXT PRIMARY KEY,
    payload       TEXT NOT NULL,
    last_activity BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_sessions_activity ON sessions (last_activity);
